Out_Q out_q_create( UInt8 free_size  ) 
{
    Out_Q out_q = (Out_Q)os_mem_request( sizeof( struct s_Out_Q ) );

    out_q->fifo_free = fifo_create(); 	
	out_q->fifo_exec = fifo_create();
    
    out_q_free_add :
    {
        UInt8 i ; 
                
        for( i = 0 ; i < free_size ; i ++ )
        {
            Out_Q_Node  *out_q_node = out_q_free_create(); 
            
            fifo_insert( out_q->fifo_free , (Fifo_Node*) out_q_node );     
        }
    }


	if( !out_q_main ) out_q_main = out_q ;
		
    return out_q ;         
}

